sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    // var allowedUser = 'instanceB.integration.user';

    // if (gs.getUserName() != allowedUser) {
    //     response.setStatus(403);
    //     response.setBody({
    //         "error": "You do not have permission to trigger this integration."
    //     });
    //     return;
    // }

    var requestBody = request.body.data;
    var responseMessage = {};

    if (!requestBody || requestBody.correlation_id == undefined || requestBody.correlation_id == '') {
        response.setStatus(400);
        responseMessage.error = "Please provide a correlation_id";
        response.setBody(responseMessage);
        return;
    }

    var assetRecord = new GlideRecord('x_2180885_it_ass_0_asset_request_table');
    assetRecord.addQuery('correlation_id', requestBody.correlation_id);
    assetRecord.setLimit(1);
    assetRecord.query();

    if (assetRecord.next()) {

        if (requestBody.short_description != undefined) assetRecord.short_description = requestBody.short_description;
        if (requestBody.description != undefined) assetRecord.description = requestBody.description;

        if (requestBody.status != undefined) assetRecord.status = requestBody.status;
        if (requestBody.priority != undefined) assetRecord.priority = requestBody.priority;
        if (requestBody.type_of_asset != undefined) assetRecord.type_of_asset = requestBody.type_of_asset;
        if (requestBody.consumables != undefined) assetRecord.consumables = requestBody.consumables;

        if (requestBody.requestor != undefined) assetRecord.requestor = requestBody.requestor;
        if (requestBody.assignment_group != undefined) assetRecord.assignment_group = requestBody.assignment_group;
        if (requestBody.assigned_to != undefined) assetRecord.assigned_to = requestBody.assigned_to;
        if (requestBody.company != undefined) assetRecord.company = requestBody.company;

        assetRecord.update();

        responseMessage.message = "Record updated successfully";
        responseMessage.number = assetRecord.number.toString();
        responseMessage.sys_id = assetRecord.sys_id.toString();

        response.setStatus(200);

    } else {

        assetRecord.initialize();
        assetRecord.correlation_id = requestBody.correlation_id;

        if (requestBody.short_description != undefined) assetRecord.short_description = requestBody.short_description;
        if (requestBody.description != undefined) assetRecord.description = requestBody.description;

        if (requestBody.status != undefined) assetRecord.status = requestBody.status;
        if (requestBody.priority != undefined) assetRecord.priority = requestBody.priority;
        if (requestBody.type_of_asset != undefined) assetRecord.type_of_asset = requestBody.type_of_asset;
        if (requestBody.consumables != undefined) assetRecord.consumables = requestBody.consumables;

        if (requestBody.requestor != undefined) assetRecord.requestor = requestBody.requestor;
        if (requestBody.assignment_group != undefined) assetRecord.assignment_group = requestBody.assignment_group;
        if (requestBody.assigned_to != undefined) assetRecord.assigned_to = requestBody.assigned_to;
        if (requestBody.company != undefined) assetRecord.company = requestBody.company;

        var newSysId = assetRecord.insert();

        responseMessage.message = "Record created successfully";
        responseMessage.number = assetRecord.number.toString();
        responseMessage.sys_id = newSysId;

        response.setStatus(201);
    }

    response.setBody(responseMessage);

})(request, response);
